        public static List<PopupReportStatsMockViewModel> PopupReportData { get; set; } = GeneratePopupReportData();

        public static List<PopupReportStatsMockViewModel> GeneratePopupReportData()
        {
            var random = new Random();

            var allPopups = ModulesMockData.StagingData.AllPopupsData;

            var popupId = random.Next(1, 1000);

            var result = new List<PopupReportStatsMockViewModel>();

            for (int i = 0; i <= allPopups.Count; i++)
            {
                var popup = allPopups[i];

                var popupEvents = new PopupReportStatsMockViewModel
                {
                    PopupId = popup.Id,
                    PopupTitle = popup.HeaderText,
                    EffectiveFrom = popup.EffectiveFrom,
                    EffectiveTo = popup.EffectiveTo,
                    PopupReportTitle = $"({popup.Id}) {popup.HeaderText}",
                    PopupReportTimeframe = "Last 30 Days",

                    Delivered = random.Next(0, 1000),
                    NotDelivered = random.Next(0, 100),

                    Click = random.Next(0, 500),
                    Dismiss = random.Next(0, 500),
                    Snooze = random.Next(0, 300),
                    AutoHide = random.Next(0, 300),
                    Show = random.Next(0, 1000),

                    // Populate response breakdowns and outstanding data
                    ResponseBreakdown = GenerateResponseBreakDownList(random.Next(0, 100), popup.EffectiveFrom, popup.EffectiveTo),

                    PopupOutstandings = GenerateOutstandingList(5),
                };

                popupEvents.Targeted = popupEvents.Delivered + popupEvents.NotDelivered;

                result.Add(popupEvents);
            }

            return result;
        }

        private static List<PopupResponseBreakDown> GenerateResponseBreakDownList(int count, string effectiveFrom, string effectiveTo)
        {
            var list = new List<PopupResponseBreakDown>();
            var random = new Random();

            for (int i = 0; i < count; i++)
            {
                list.Add(new PopupResponseBreakDown
                {
                    Domain = random.Next(0, 2) == 0 ? MockDataHelperFunctions.GetRandomDomainName() : null,
                    UserId = MockDataHelperFunctions.GetRandomUserID(),
                    Username = null,
                    UserStatus = (UserStatus)random.Next(1, 4), // Random between Active, Inactive, NotInstalled
                    MachineId = MockDataHelperFunctions.GetRandomMachineID(),
                    MachineName = null,
                    BubbleShowDT = DateTime.Now.AddDays(-random.Next(1, 100)),
                    BubbleClickDT = DateTime.Now.AddDays(-random.Next(1, 100)),
                    BubbleDismissDT = random.Next(0, 2) == 0 ? DateTime.Now.AddDays(-random.Next(1, 100)) : null,
                    BubbleSnoozeDT = random.Next(0, 2) == 0 ? DateTime.Now.AddDays(-random.Next(1, 100)) : null,
                    BubbleAutoHideDT = random.Next(0, 2) == 0 ? DateTime.Now.AddDays(-random.Next(1, 100)) : null,
                    FeedbackLikeDislike = random.Next(0, 2) == 0 ? (random.Next(0, 2) == 0 ? "Like" : "Dislike") : null,
                    FeedbackComment = random.Next(0, 2) == 0 ? GenerateRandomFeedbackComment() : null,
                    LastSyncDT = random.Next(0, 2) == 0 ? DateTime.Now.AddDays(-random.Next(1, 100)) : null,
                    SnoozeCount = random.Next(0, 2) == 0 ? random.Next(20) : null,
                    EffectiveFrom = effectiveFrom,
                    EffectiveTo = effectiveTo
                });
            }

            return list;
        }

        private static List<PopupOutstanding> GenerateOutstandingList(int count)
        {
            var list = new List<PopupOutstanding>();
            var random = new Random();

            for (int i = 0; i < count; i++)
            {
                list.Add(new PopupOutstanding
                {
                    Domain = MockDataHelperFunctions.GetRandomDomainName(),
                    UserId = MockDataHelperFunctions.GetRandomUserID(),
                    Username = null,
                    UserStatus = (UserStatus)random.Next(1, 4), // Random between Active, Inactive, NotInstalled
                    MachineId = MockDataHelperFunctions.GetRandomMachineID(),
                    MachineName = null,
                    LastSyncDT = DateTime.Now.AddDays(-random.Next(1, 100))
                });
            }

            return list;
        }

        private static string GenerateRandomFeedbackComment()
        {
            var comments = new List<string> { "Good feature", "Annoying popup", "Helpful", "Not useful" };
            var random = new Random();
            return comments[random.Next(comments.Count)];
        }

